INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3125, 'https://international.iitkgp.ac.in/scholarships/gkif/', 'Guru Krupa Foundation (GKF) USA - Postgraduate Scholarship for International Students | IIT Kharagpur International Relations (official)', 'international.iitkgp.ac.in', 'scholarship', now(), true, true, now()), (3126, 'https://www.uu.se/en/study/masters-studies/scholarships/uppsala-university-scholarships', $$Uppsala University Master's scholarships (incl. Uppsala University Global Scholarship) | Uppsala University (official)$$, 'uu.se', 'scholarship', now(), true, true, now());

-- 2. Scholarship 987 (GKF, IIT Kharagpur)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES (987, $$Guru Krupa Foundation Postgraduate Scholarship for International Students (IIT Kharagpur)$$, $$Guru Krupa Foundation (USA)$$, $$India$$, $$Full Tuition + Stipend$$, 0, $$No fixed closing date is published. The Office of International Relations releases the call normally in January every year; only bonafide (already enrolled) international postgraduate students at IIT Kharagpur may apply, by filling in the form against that call. This award cannot be applied for before enrolling at IIT Kharagpur.$$ , $$["Master's", "PhD"]$$, $$["All disciplines - postgraduate level at IIT Kharagpur (per the GKF page: 'across all disciplines')"]$$, NULL, NULL, false, true, $$The Guru Krupa Foundation (GKF), USA funds a named scholarship for international postgraduates ALREADY STUDYING at IIT Kharagpur. Per the fetched Office of International Relations page, GKF "supports meritorious self-funded international students of Postgraduate level across all disciplines in the form of awarding scholarships of up to INR 25,000 per month to cover tuition fees, hostel/accommodation charges, mess charges, living expenses", and awardees are selected based on academic excellence. Understand what kind of award this is before planning around it: it is a CONTINUING-student scholarship, not an entry offer - applicants must be bonafide IIT Kharagpur students responding to the annual call of the Office of International Relations (normally released in January), hold a CGPA of at least 8.5 with no backlog in any subject, have no disciplinary action taken against them during their stay, and not be receiving any financial support from the Institute or an outside sponsor (so holders of institute assistantships or fellowships are outside its audience). The scholarship is awarded for one year; the student may apply again against the next call. The Foundation was founded by IIT Kharagpur alumnus Dr Mukund Padmanabhan (Renaissance Technologies). Two neighbouring items on the same International Relations menu are out of scope here: ADSIP is a full scholarship restricted to SAARC nationals, and the GKF internship programme described on the same page supports DOMESTIC IIT Kharagpur students taking internships abroad. Incoming applicants should therefore plan admission and initial funding separately, and treat this record as funding to compete for after enrolling self-funded at IIT Kharagpur.$$ , $$Eligibility (fetched GKF page): you are a self-funded international student of postgraduate level enrolled at IIT Kharagpur (any discipline); no disciplinary action has been taken against you during your stay at IIT Kharagpur; your CGPA is at least 8.5 (IIT Kharagpur's 10-point scale) with no backlog in any subject; and you are not a recipient of any financial support from the Institute or an outside sponsor. Selection is based on academic excellence. Application process: bonafide students apply against the call released by the Office of International Relations by filling up the form; the call is released normally in January every year. The scholarship is awarded for one year and may be applied for again against the next call. Note the structural constraint: because an IIT Kharagpur transcript and an 8.5+ CGPA at the institute are required, this scholarship becomes reachable only after at least initial enrolled study at IIT Kharagpur - it does not fund the application or admission stage.$$ , $$https://international.iitkgp.ac.in/scholarships/gkif/$$, $$["International (non-Indian) postgraduate students ENROLLED at IIT Kharagpur who are self-funded - not recipients of institute or outside-sponsor financial support"]$$, $$Donor-funded monthly scholarship (Guru Krupa Foundation, USA; call run by IIT Kharagpur's Office of International Relations): up to INR 25,000 per month toward tuition fees, hostel/accommodation charges, mess charges and living expenses; awarded for one year, renewable by re-applying against the next annual (normally January) call.$$ , $$Up to INR 25,000 per month, intended to cover tuition fees, hostel/accommodation, mess and living expenses for one year; the exact awarded amount is set per awardee ('up to'), so no fixed figure is stored.$$ , NULL, NULL, $$Covered among the heads the monthly scholarship is meant to pay for (hostel/accommodation charges, up to the awarded amount) - no separate housing entitlement is published.$$ , NULL, $$No English-test requirement is published for this scholarship on the fetched page; it is awarded to students already enrolled in IIT Kharagpur postgraduate programmes (English-medium), on academic excellence.$$ , $$["Transcript from IIT Kharagpur", "Academic transcript of the Bachelor's programme", "Letter of endorsement from the Head of the Department/School/Centre", "Letter of recommendation", "The application form against the Office of International Relations call (normally released in January)"]$$, $$https://international.iitkgp.ac.in/scholarships/gkif/$$, NULL, NULL, $$not_published$$, NULL, NULL, $$[{"pattern": "Annual call by the Office of International Relations, normally released in January; only bonafide enrolled international postgraduates at IIT Kharagpur may apply. Awards run one year and can be re-applied for against the next call."}]$$, $$annual$$, NULL, NULL, $$upcoming$$, now(), now(), $$verified$$, 10, $$https://international.iitkgp.ac.in/scholarships/gkif/$$, $$ADDED 2026-10-28 (enrichment batch 26) from the GKF page fetched first-hand in Pass 119 and re-fetched today (source 3125): up-to INR 25,000/month, self-funded enrolled international postgraduates, CGPA >= 8.5 with no backlog, no other support, no disciplinary action, annual January IR-office call, one-year award. award_amount NULL per the house 'up to'/variable rule (the cap is carried in the texts); min_gpa NULL because the 8.5 figure is an in-institute CGPA on a 10-point scale for a continuing-student award, not an admission threshold; min_ielts NULL (none published). Degrees Master's/PhD per 'postgraduate level across all disciplines'. NOT a rewrite of retired 397 (whose title identified the domestic MCM/freeship family); this is the separate international scheme verified in Pass 119 and added under its own identity. Sibling schemes mentioned only: ADSIP (SAARC-only), SGRIP (visiting faculty/postdocs), GKF internship programme (domestic outbound). Non-USD award: amount_usd_value = 0.$$ , true, 316, NULL, $$INR$$, $$month$$, $$variable$$);

-- 3. Record 773 (Uppsala Global) uplift
UPDATE scholarships SET title = $$Uppsala University Global Scholarship$$, provider = $$Uppsala University$$, country = $$Sweden$$, coverage_type = $$Full Tuition Waiver$$, amount_usd_value = 0, award_amount = NULL, award_currency = $$SEK$$, award_period = $$year$$, award_basis = $$variable$$, deadline = $$Scholarship application for autumn 2027 starters is open 16 January - 1 February 2027 (Uppsala's own form). You must first have applied for the Master's programme through universityadmissions.se by the University Admissions deadline (15 January 2027) with Uppsala ranked as your first priority, and the application fee and complete supporting documents must reach University Admissions before their deadlines.$$ , deadline_date = '2027-02-01', deadline_type = $$fixed$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[{"cycle": "Autumn 2027 entry", "programme_deadline": "2027-01-15 (University Admissions deadline; rank the Uppsala programme FIRST priority)", "scholarship_opens": "2027-01-16", "deadline": "2027-02-01", "status": "programme applications open now; scholarship form opens 16 January 2027 - only about 2% of applicants are granted a scholarship"}]$$, recurrence = $$annual$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Master's"]$$, eligible_majors = $$["International Master's programmes at Uppsala University - EXCEPT the programmes on Uppsala's ineligibility list (e.g. Joint Nordic Master's in Environmental Law; EACH; NABiS; Euroculture; MEME; Global Markets, Local Creativities; ITS; International Humanitarian Action; PANGEA; Religion in Peace and Conflict; Transformative Game Design)"]$$, eligible_countries = $$["Citizens of countries outside the EU/EEA and Switzerland (fee-paying international Master's applicants)"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$Sweden charges tuition to students from outside the EU/EEA, and the Uppsala University Global Scholarship - funded by the Swedish Council for Higher Education (UHR), the government agency responsible for Swedish higher education - removes that fee entirely for a selected group of international Master's students: it covers the full tuition fee for an international Master's programme at Uppsala University and nothing else, with living expenses explicitly not covered. Uppsala warns that the scholarships are highly competitive - only about 2% of those who apply are granted one - and that the scholarships available for application may vary from year to year. Unlike Stockholm University's scheme (record 673), Uppsala runs its own scholarship application round BEFORE admission results: for autumn 2027 starters the form is open 16 January to 1 February 2027, but eligibility is decided earlier by two hard gates - you must have applied for the Master's programme before the University Admissions deadline, and the Uppsala programme must be the one you ranked FIRST priority among your choices at University Admissions; a Global Scholarship can only be awarded for that first-priority programme. Eleven named (mostly joint/Erasmus-style) Master's programmes are excluded from Uppsala scholarships altogether - check the fetched list before choosing. The sibling Anders Wall Scholarship on the same page also covers full tuition but is restricted to citizens of African countries (Bachelor's and Master's), so it is out of scope for most readers here and is not given its own record.$$ , requirements = $$Eligibility (fetched Uppsala page): be a citizen of a country outside the EU/EEA and Switzerland; demonstrate academic talent and show interest in being in an educational environment (Uppsala publishes no GPA or English-score cut-off for the scholarship - entry requirements are those of the programme); the scholarship can only be awarded for a Master's programme at Uppsala University chosen as FIRST PRIORITY (ranked highest of the programmes you choose at University Admissions); you must have applied for the Master's programme before the University Admissions deadline and meet its entry requirements, with the application fee and your complete supporting documents received by University Admissions before the deadline. Order of operations: (1) apply for the programme at universityadmissions.se by 15 January 2027 with Uppsala ranked first; (2) submit Uppsala's separate scholarship application in the window 16 January - 1 February 2027 (for autumn 2027). Only about 2% of applicants are granted a scholarship, and living costs must be financed independently. Students admitted to the eleven programmes on Uppsala's restrictions list (Joint Nordic Master's in Environmental Law, EACH, NABiS, Euroculture, MEME, Global Markets/Local Creativities, Implementation/Transformative Learning and Sustainability, International Humanitarian Action, PANGEA, Religion in Peace and Conflict, Transformative Game Design) are NOT eligible for scholarships offered by Uppsala University. Questions: tuitiongrants@uu.se.$$ , website_url = $$https://www.uu.se/en/study/masters-studies/scholarships/uppsala-university-scholarships$$, source_url = $$https://www.uu.se/en/study/masters-studies/scholarships/uppsala-university-scholarships$$, application_url = $$https://www.uu.se/en/study/masters-studies/scholarships/application-guide$$, funding_type = $$Government-funded (Swedish Council for Higher Education, UHR) merit-based full tuition waiver for international Master's programmes; about 2% of applicants are granted one$$, tuition_coverage = $$The full tuition fee for an international Master's programme at Uppsala University (the waived amount therefore varies by programme and no single figure is stored); living expenses are not covered.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = $$Not covered - the scholarship pays the tuition fee only; living expenses are explicitly the student's own (per Uppsala).$$ , application_fee = NULL, english_requirements = $$The scholarship sets no separate English score; you must meet the entry requirements (including English) of the chosen Master's programme, evidenced through University Admissions.$$ , required_documents = $$["University Admissions application (universityadmissions.se) with the Uppsala programme ranked FIRST priority, submitted before the 15 January deadline", "Application fee and complete supporting documents received by University Admissions before their deadlines", "Bachelor's degree certificate and transcripts meeting the programme's entry requirements", "Proof of English proficiency meeting the chosen programme's requirement", "Uppsala's separate scholarship application, submitted in the 16 January - 1 February window (autumn 2027 cycle)"]$$, application_status = $$open$$, verification_status = $$verified$$, source_reliability = 10, is_active = true, university_id = 90, notes = $$BATCH 26 UPLIFT 2026-10-28 (rel 8 -> 10): re-verified first-hand on the fetched UU Master's-scholarships page (new source 3126). CORRECTIONS to the 2026-10-23 state: (1) degree_levels Bachelor/Master -> Master's only (the fetched page restricts the Global Scholarship to Master's programmes; the Bachelor's element on that page belongs to the Africa-only Anders Wall Scholarship, now mention-only here); vocabulary also normalized to apostrophe forms. (2) deadline_date 2027-01-15 (the ADMISSION deadline) -> 2027-02-01, the fetched scholarship-round close for autumn 2027 (form open 16 Jan-1 Feb 2027), type fixed, with both dates sequenced in rounds. (3) min_gpa 3.3 / min_ielts 6.5 REMOVED - no cut-offs are published (academic-talent selection; English per programme); us 87 carried the same invented profile and is resynced. (4) award_basis 'full_tuition' -> 'variable' for consistency with the Swedish cluster (fee waived varies by programme; amount stays NULL); coverage 'Full Tuition' -> 'Full Tuition Waiver'. (5) eligible_countries 'All' -> the non-EU/EEA/Swiss scope; the 11 ineligible programmes and the ~2% success rate from the fetched page are now in the texts; source link (773, 3126) added (row previously had none).$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 773;

