INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at, created_at) VALUES (710, 316, 987, $$Guru Krupa Foundation Postgraduate Scholarship for International Students$$, 'available', $$Donor-funded monthly scholarship (Guru Krupa Foundation, USA) via the IR Office annual call$$, $$Up to INR 25,000 per month toward tuition, hostel, mess and living costs (one year)$$, true, true, $$The named continuing-student award for self-funded international postgraduates already enrolled at IIT Kharagpur$$, $$Enrolled self-funded international postgraduates only (all disciplines): CGPA >= 8.5 with no backlog, no disciplinary action, and no other institute/outside financial support. Apply against the Office of International Relations call (normally each January) with IIT KGP + bachelor's transcripts, HoD endorsement and a recommendation. One-year award, re-applicable. Cannot be applied for before enrolment.$$ , 'https://international.iitkgp.ac.in/scholarships/gkif/', 'https://international.iitkgp.ac.in/scholarships/gkif/', 'verified_official_source', now(), now());

UPDATE university_scholarships SET scholarship_name = $$Uppsala University Global Scholarship$$, availability_status = $$available$$, funding_type = $$Government-funded (Swedish Council for Higher Education) merit-based full tuition waiver$$, max_scholarship = $$Full tuition fee for an international Master's programme (varies by programme; living costs not covered; ~2% of applicants succeed)$$, covers_tuition = true, covers_living_expenses = false, valued_aspect = $$Full tuition waiver decided in Uppsala's own January scholarship round - but only for the programme ranked FIRST at University Admissions$$, eligibility_notes = $$Citizens outside the EU/EEA and Switzerland applying to an international Master's at Uppsala (fetched page: Master's level only for the Global Scholarship). Must rank the Uppsala programme first priority, apply by the University Admissions deadline (15 Jan 2027) with fee + complete documents in on time, then file Uppsala's scholarship form 16 January - 1 February 2027 (autumn 2027). No published GPA/English cut-off (academic-talent selection; English per programme). Eleven named joint programmes are ineligible.$$ , official_url = $$https://www.uu.se/en/study/masters-studies/scholarships/uppsala-university-scholarships$$, source_url = $$https://www.uu.se/en/study/masters-studies/scholarships/uppsala-university-scholarships$$, verification_status = $$verified_official_source$$, last_verified_at = now() WHERE id = 87;
